const j = $json;
let cfg = {}, creative = {};
try { cfg = typeof j.platform_config === 'string' ? JSON.parse(j.platform_config) : (j.platform_config || {}); } catch (e) { cfg = {}; }
try { creative = typeof j.creative === 'string' ? JSON.parse(j.creative) : (j.creative || {}); } catch (e) { creative = {}; }

const igUserId = cfg.ig_user_id || $env.META_IG_USER_ID;
const caption = [String(creative.caption || '').trim(), String(creative.cta || '').trim(), (creative.hashtags || []).join(' ')]
  .filter(Boolean).join('\n\n').slice(0, 2200);

const errors = [];
if (!igUserId) errors.push('missing_ig_user_id');
if (!caption) errors.push('missing_caption');
if (!/^https?:\/\//i.test(String(j.storage_ref || ''))) errors.push('image_reference_not_public_url');

return {
  json: {
    schedule_id: j.schedule_id,
    asset_id: j.asset_id,
    campaign_id: j.campaign_id,
    client_id: j.client_id,
    platform: 'instagram',
    ready: errors.length === 0,
    prep_errors: errors,
    ig_user_id: igUserId,
    api_version: $env.META_API_VERSION || 'v21.0',
    caption,
    image_url: j.storage_ref
  }
};

const prep = $('CODE - Instagram Media Preparation').first().json;
const r = $input.first().json || {};
const mediaId = r.id || null;
return [{
  json: {
    ...prep,
    status: mediaId ? 'published' : 'failed',
    platform_post_id: mediaId,
    published_at: new Date().toISOString(),
    raw_response: { container: $('HTTP - Instagram Create Container').first().json, publish: r },
    error_detail: mediaId ? null : { stage: 'publication', platform: 'instagram', error_code: 'no_media_id_returned', message: 'media_publish returned no id', retry_count: 0, timestamp: new Date().toISOString() }
  }
}];

const prep = $('CODE - Instagram Media Preparation').first().json;
const e = $input.first().json || {};
const code = e.error?.error?.code || e.error?.code || e.code || 'graph_api_error';
const msg = e.error?.error?.message || e.error?.message || e.message || 'Instagram publication failed';
return [{
  json: {
    ...prep,
    status: 'failed',
    platform_post_id: null,
    published_at: null,
    raw_response: e,
    error_detail: { stage: 'publication', platform: 'instagram', error_code: String(code), message: String(msg), retry_count: 3, timestamp: new Date().toISOString() }
  }
}];
